from collections import deque

class MovingAverage:
    def __init__(self, size):
        self.q=deque()
        self.size=size
        self.total=0

    def next(self,val):
        self.q.append(val)
        self.total+=val

        if len(self.q)>self.size:
            self.total-=self.q.popleft()

        return self.total/len(self.q)

import java.util.*;

class MovingAverage {
    Queue<Integer> q=new LinkedList<>();
    int size;
    double sum=0;

    public MovingAverage(int size){
        this.size=size;
    }

    public double next(int val){
        q.add(val);
        sum+=val;

        if(q.size()>size)
            sum-=q.poll();

        return sum/q.size();
    }
}

