class Solution {
public:
    string predictPartyVictory(string senate) {
        queue<int> rq, dq;
        int n = senate.size();
        for(int i = 0; i < n; i++) {
            if(senate[i] == 'R') rq.push(i);
            else dq.push(i);
        }
        while(!rq.empty() && !dq.empty()) {
            int r_idx = rq.front(); rq.pop();
            int d_idx = dq.front(); dq.pop();
            if(r_idx < d_idx) rq.push(r_idx + n);
            else dq.push(d_idx + n);
        }
        return rq.empty() ? "Dire" : "Radiant";
    }
};

def truckTour(pumps):
    start=0
    tank=0
    total=0

    for i,(petrol,dist) in enumerate(pumps):
        tank+=petrol-dist

        if tank<0:
            start=i+1
            total+=tank
            tank=0

    if total+tank>=0:
        return start

    return -1

class Solution{
