        int start=0,tank=0,total=0;

        for(int i=0;i<pumps.length;i++){
            tank+=pumps[i][0]-pumps[i][1];

            if(tank<0){
                start=i+1;
                total+=tank;
                tank=0;
            }
        }

        return (total+tank>=0)?start:-1;
    }
