class FrontMiddleBackQueue {
    deque<int> a, b;
    void balance() {
        if(a.size() > b.size()) { b.push_front(a.back()); a.pop_back(); }
        else if(b.size() > a.size() + 1) { a.push_back(b.front()); b.pop_front(); }
    }
public:
    void pushFront(int val) { a.push_front(val); balance(); }
    void pushMiddle(int val) { if(a.size() < b.size()) a.push_back(val); else b.push_front(val); balance(); }
    void pushBack(int val) { b.push_back(val); balance(); }
    int popFront() {
        if(a.empty() && b.empty()) return -1;
        int res;
        if(a.empty()) { res = b.front(); b.pop_front(); }
        else { res = a.front(); a.pop_front(); }
        balance(); return res;
    }
    int popMiddle() {
        if(a.empty() && b.empty()) return -1;
        int res;
        if(a.size() == b.size()) { res = a.back(); a.pop_back(); }
        else { res = b.front(); b.pop_front(); }
        balance(); return res;
    }
    int popBack() {
        if(b.empty()) return -1;
        int res = b.back(); b.pop_back();
        balance(); return res;
    }
};

