        self.k=k
        self.q=deque()

    def addElement(self,num):
        self.q.append(num)
        if len(self.q)>self.m:
            self.q.popleft()

    def calculateMKAverage(self):
        if len(self.q)<self.m:
            return -1
        arr=sorted(self.q)
        arr=arr[self.k:self.m-self.k]
        return sum(arr)//len(arr)

