using namespace std;
class MKAverage {
    int m, k, count = 0;
    queue<int> q;
    multiset<int> lower, middle, upper;
    long long midSum = 0;

    void add(int num) {
        if(lower.empty() || num <= *lower.rbegin()) { lower.insert(num); }
        else if(middle.empty() || num <= *middle.rbegin()) { middle.insert(num); midSum += num; }
        else { upper.insert(num); }
    }

    void remove(int num) {
        if(lower.find(num) != lower.end()) { lower.erase(lower.find(num)); }
        else if(middle.find(num) != middle.end()) { middle.erase(middle.find(num)); midSum -= num; }
        else { upper.erase(upper.find(num)); }
    }

    void balance() {
        while(lower.size() < k) {
            if(!middle.empty()) { int v = *middle.begin(); middle.erase(middle.begin()); midSum -= v; lower.insert(v); }
            else { int v = *upper.begin(); upper.erase(upper.begin()); lower.insert(v); }
        }
        while(lower.size() > k) { int v = *lower.rbegin(); lower.erase(std::prev(lower.end())); middle.insert(v); midSum += v; }

        while(upper.size() < k) { int v = *middle.rbegin(); middle.erase(std::prev(middle.end())); midSum -= v; upper.insert(v); }
        while(upper.size() > k) { int v = *upper.begin(); upper.erase(upper.begin()); middle.insert(v); midSum += v; }
    }
public:
    MKAverage(int m, int k) : m(m), k(k) {}

    void addElement(int num) {
        q.push(num); count++; add(num);
        if(count > m) { int rem = q.front(); q.pop(); remove(rem); count--; }
        if(count == m) balance();
    }

    int calculateMKAverage() {
        if(count < m) return -1;
        return midSum / (m - 2*k);
    }
};

