class Solution {
public:
    int maximumRobots(vector<int>& chargeTimes, vector<int>& runningCosts, long long budget) {
        int res = 0, n = chargeTimes.size(), l = 0;
        long long sum = 0;
        deque<int> d;
        for(int r = 0; r < n; r++) {
            sum += runningCosts[r];
            while(!d.empty() && chargeTimes[d.back()] <= chargeTimes[r]) d.pop_back();
            d.push_back(r);
            while(l <= r && (d.empty() ? 0 : chargeTimes[d.front()]) + (r - l + 1) * sum > budget) {
                sum -= runningCosts[l];
                if(!d.empty() && d.front() == l) d.pop_front();
                l++;
            }
            res = max(res, r - l + 1);
        }
        return res;
    }
};

