class Solution {
public:
    vector<int> timeTaken(vector<int>& arrival, vector<int>& state) {
        int n = arrival.size();
        vector<int> res(n);
        queue<int> enter, exit;
        for(int i = 0; i < n; i++) {
            if(state[i] == 0) enter.push(i);
            else exit.push(i);
        }
        int time = 0, prev = 1;
        while(!enter.empty() || !exit.empty()) {
            if(!enter.empty() && arrival[enter.front()] <= time && !exit.empty() && arrival[exit.front()] <= time) {
                if(prev == 1) { res[exit.front()] = time; exit.pop(); prev = 1; }
                else { res[enter.front()] = time; enter.pop(); prev = 0; }
            } else if(!exit.empty() && arrival[exit.front()] <= time) {
                res[exit.front()] = time; exit.pop(); prev = 1;
            } else if(!enter.empty() && arrival[enter.front()] <= time) {
                res[enter.front()] = time; enter.pop(); prev = 0;
            } else {
                int nextTime = INT_MAX;
                if(!enter.empty()) nextTime = min(nextTime, arrival[enter.front()]);
                if(!exit.empty()) nextTime = min(nextTime, arrival[exit.front()]);
                time = nextTime - 1;
                prev = 1;
            }
            time++;
        }
        return res;
    }
};

