class Solution {
public:
    int kEmptySlots(vector<int>& bulbs, int k) {
        int n = bulbs.size();
        vector<int> days(n + 1);
        for(int i = 0; i < n; i++) days[bulbs[i]] = i + 1;
        int l = 1, r = k + 2, res = INT_MAX;
        for(int i = 1; r <= n; i++) {
            if(days[i] > max(days[l], days[r])) continue;
            if(i == r) res = min(res, max(days[l], days[r]));
            l = i; r = i + k + 1;
        }
        return res == INT_MAX ? -1 : res;
    }
};

