from collections import deque

def snakesAndLadders(board):
    n=len(board)

    def id2pos(id):
        r=(id-1)//n
        c=(id-1)%n
        if r%2:
            c=n-1-c
        return n-1-r,c

    q=deque([(1,0)])
    visited={1}

    while q:
        s,steps=q.popleft()

        if s==n*n:
            return steps

        for i in range(1,7):
            ns=s+i
            if ns>n*n: break

            r,c=id2pos(ns)

            if board[r][c]!=-1:
                ns=board[r][c]

            if ns not in visited:
                visited.add(ns)
                q.append((ns,steps+1))

    return -1

