import java.util.*;
class Solution{}

#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        auto getCoord = [&](int s) {
            int r = n - 1 - (s - 1) / n;
            int c = (s - 1) % n;
            if((n - 1 - r) % 2 != 0) c = n - 1 - c;
            return make_pair(r, c);
        };
        queue<int> q;
        vector<bool> vis(n * n + 1, false);
        q.push(1); vis[1] = true;
        int moves = 0;
        while(!q.empty()) {
            int sz = q.size();
            for(int i = 0; i < sz; i++) {
                int curr = q.front(); q.pop();
                if(curr == n * n) return moves;
                for(int next = curr + 1; next <= min(curr + 6, n * n); next++) {
                    auto [r, c] = getCoord(next);
                    int dest = board[r][c] != -1 ? board[r][c] : next;
                    if(!vis[dest]) { vis[dest] = true; q.push(dest); }
                }
            }
            moves++;
        }
        return -1;
    }
};

