class Solution {
    // This assumes a generic packet router simulation where packets are queued and dequeued based on some logic. 
    // Usually it resembles wait time calculation.
public:
    vector<int> processPackets(vector<vector<int>>& packets, int capacity) {
        queue<pair<int, int>> q;
        int time = 0;
        vector<int> res;
        for(auto& p : packets) {
            time = max(time, p[0]);
            while(!q.empty() && q.front().first + q.front().second <= p[0]) {
                int start = max(time, q.front().first);
                time = start + q.front().second;
                q.pop();
            }
            if(q.size() < capacity) {
                q.push({p[0], p[1]});
                res.push_back(time + p[1]);
                time += p[1];
            } else {
                res.push_back(-1);
            }
        }
        return res;
    }
};

