using namespace std;
class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        int res = 0;
        stack<int> st;
        heights.push_back(0);
        for(int i = 0; i < heights.size(); i++) {
            while(!st.empty() && heights[st.top()] > heights[i]) {
                int h = heights[st.top()]; st.pop();
                int w = st.empty() ? i : i - st.top() - 1;
                res = max(res, h * w);
            }
            st.push(i);
        }
        heights.pop_back();
        return res;
    }
};

def trap(height):
    stack=[]
    water=0

    for i,h in enumerate(height):
        while stack and h>height[stack[-1]]:
            mid=stack.pop()

            if not stack:
                break

            dist=i-stack[-1]-1
            bounded=min(h,height[stack[-1]])-height[mid]

            water+=dist*bounded

        stack.append(i)

    return water

// Stack water trapping
import java.util.*;
class Solution{}

#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int trap(vector<int>& height) {
        int l = 0, r = height.size() - 1, res = 0, maxl = 0, maxr = 0;
        while(l <= r) {
            if(maxl <= maxr) {
                res += max(0, maxl - height[l]);
                maxl = max(maxl, height[l]);
                l++;
            } else {
                res += max(0, maxr - height[r]);
                maxr = max(maxr, height[r]);
                r--;
            }
        }
        return res;
    }
};

def subArrayRanges(nums):
    res=0
    n=len(nums)

    for i in range(n):
        mn=mx=nums[i]
        for j in range(i,n):
            mn=min(mn,nums[j])
            mx=max(mx,nums[j])
            res+=mx-mn

    return res

// Brute force demonstration
import java.util.*;
class Solution{}

#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    long long subArrayRanges(vector<int>& nums) {
        int n = nums.size();
        long long res = 0;
        stack<int> st;
        vector<int> left(n), right(n);
        for(int i = 0; i < n; i++) {
            while(!st.empty() && nums[st.top()] > nums[i]) st.pop();
            left[i] = st.empty() ? i + 1 : i - st.top();
            st.push(i);
        }
        while(!st.empty()) st.pop();
        for(int i = n - 1; i >= 0; i--) {
            while(!st.empty() && nums[st.top()] >= nums[i]) st.pop();
            right[i] = st.empty() ? n - i : st.top() - i;
            st.push(i);
        }
        for(int i = 0; i < n; i++) res -= (long long)nums[i] * left[i] * right[i];
        while(!st.empty()) st.pop();
        for(int i = 0; i < n; i++) {
            while(!st.empty() && nums[st.top()] < nums[i]) st.pop();
            left[i] = st.empty() ? i + 1 : i - st.top();
            st.push(i);
        }
        while(!st.empty()) st.pop();
        for(int i = n - 1; i >= 0; i--) {
            while(!st.empty() && nums[st.top()] <= nums[i]) st.pop();
            right[i] = st.empty() ? n - i : st.top() - i;
            st.push(i);
        }
        for(int i = 0; i < n; i++) res += (long long)nums[i] * left[i] * right[i];
        return res;
    }
};
